  var API = '/api/gps/mileage';

  var SIX_ORDER = ['机扫车', '洒水车', '机洗扫车', '皮卡车', '货车', '深度保洁车'];
  var SIX_NOTE = {
    '机扫车': '机扫车', '洒水车': '洒水车', '机洗扫车': '机洗扫车',
    '皮卡车': '皮卡车（含面包车、长安纯电皮卡）', '货车': '货车（单排/双排自卸、平板）',
    '深度保洁车': '深度保洁车', '其他': '其他车型（不参与占比）'
  };
  var SIX_COLOR = {
    '机扫车': '#2f6fed', '洒水车': '#0ea5e9', '机洗扫车': '#6366f1',
    '皮卡车': '#d97706', '货车': '#7c3aed', '深度保洁车': '#0d9488', '其他': '#94a3b8'
  };
  var WD = ['日', '一', '二', '三', '四', '五', '六'];

  function sixOf(m) {
    if (m.indexOf('机洗扫车') >= 0) return '机洗扫车';
    if (m.indexOf('机扫车') >= 0) return '机扫车';
    if (m.indexOf('洒水车') >= 0) return '洒水车';
    if (m.indexOf('皮卡') >= 0 || m.indexOf('面包车') >= 0) return '皮卡车';
    if (m.indexOf('自卸货车') >= 0 || m.indexOf('平板货车') >= 0) return '货车';
    if (m.indexOf('深度保洁车') >= 0) return '深度保洁车';
    return '其他';
  }
  function mdlTag(m) {
    if (m.indexOf('面包车') >= 0) return '面包车';
    if (m.indexOf('长安纯电') >= 0) return '长安纯电';
    if (m.indexOf('双排') >= 0) return '双排';
    if (m.indexOf('单排') >= 0) return '单排';
    if (m.indexOf('平板') >= 0) return '平板';
    return '';
  }

  /* ---------- 状态 ---------- */
  var state = { cars: [], days: {}, times: {}, months: [], minDay: '', maxDay: '', syncedAt: null, live: false };
  var dayTotal = {}, carMonth = {}, carMonthDays = {}, monthTotal = {}, clsMonth = {}, sixSum = {};
  var ALL = [], MIN = '', MAX = '';
  var curDate = '', curMonth = '', filter = 'all', keyword = '', closed = {};
  var loading = {};

  function fmt(n) {
    return (n || 0).toLocaleString('zh-CN', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  }
  function fmtInt(n) { return Math.round(n || 0).toLocaleString('zh-CN'); }

  function ingest(p) {
    if (p.cars && p.cars.length) {
      state.cars = p.cars.map(function (c) {
        return { carId: String(c.carId), plate: c.plate, model: c.model || '', cat: c.cat || 'work',
                 cls: sixOf(c.model || '') };
      });
      state.cars.sort(function (a, b) { return a.plate.localeCompare(b.plate, 'zh-CN'); });
    }
    var d = p.days || {};
    Object.keys(d).forEach(function (k) { state.days[k] = d[k]; });
    var t = p.times || {};
    Object.keys(t).forEach(function (k) { state.times[k] = t[k]; });
    if (p.months) state.months = p.months;
    if (p.minDay) state.minDay = p.minDay;
    if (p.maxDay) state.maxDay = p.maxDay;
    if (p.syncedAt) state.syncedAt = p.syncedAt;
    buildIndex();
  }

  function buildIndex() {
    dayTotal = {}; carMonth = {}; carMonthDays = {}; monthTotal = {}; clsMonth = {}; sixSum = {};
    ALL = Object.keys(state.days).sort();
    MIN = state.minDay || ALL[0] || '';
    MAX = state.maxDay || ALL[ALL.length - 1] || '';

    ALL.forEach(function (d) {
      var ym = d.slice(0, 7), t = 0, rec = state.days[d];
      for (var id in rec) {
        var km = rec[id];
        t += km;
        (carMonth[ym] || (carMonth[ym] = {}))[id] = (carMonth[ym][id] || 0) + km;
        (carMonthDays[ym] || (carMonthDays[ym] = {}))[id] = (carMonthDays[ym][id] || 0) + 1;
      }
      dayTotal[d] = +t.toFixed(1);
      monthTotal[ym] = +((monthTotal[ym] || 0) + t).toFixed(1);
    });
    Object.keys(carMonth).forEach(function (ym) {
      var o = clsMonth[ym] = {};
      state.cars.forEach(function (c) {
        o[c.cls] = (o[c.cls] || 0) + (carMonth[ym][c.carId] || 0);
      });
      sixSum[ym] = SIX_ORDER.reduce(function (s, k) { return s + (o[k] || 0); }, 0);
    });
  }

  function loadMonth(ym) {
    if (loading[ym]) return loading[ym];
    loading[ym] = fetch(API + '?month=' + ym, { headers: { Accept: 'application/json' } })
      .then(function (r) { return r.json(); })
      .then(function (j) {
        if (j && j.ok && j.data) { ingest(j.data); state.live = true; }
        return true;
      })
      .catch(function () { return false; })
      .then(function (r) { delete loading[ym]; return r; });
    return loading[ym];
  }

